-- Reference tables: the public rows of the Salo Evening Dataset that the app reads.
-- Loaded by supabase/seed.sql (generated by scripts/gen-supabase-seed.mjs).
-- No dataset messages and no pilot or main evening data are stored anywhere in this database.

create table public.donors (
  id text primary key check (id ~ '^D[0-9]{2}$'),
  name text not null check (char_length(name) between 1 and 200),
  type text not null check (type in (
    'karinderya', 'panaderia', 'carinderia-canteen', 'small grocery stall',
    'catering kitchen', 'fruit & vegetable stall')),
  street text not null check (char_length(street) between 1 and 200),
  -- closing_time from donors.csv, as minutes after local midnight (Asia/Manila).
  closing_minute int not null check (closing_minute between 960 and 1320),
  anchor boolean not null
);

create table public.pantries (
  id text primary key check (id ~ '^P[0-9]{2}$'),
  name text not null check (char_length(name) between 1 and 200),
  type text not null check (type in (
    'feeding program', 'parish kitchen', 'community pantry', 'barangay kitchen')),
  street text not null check (char_length(street) between 1 and 200),
  opens_minute int not null check (opens_minute between 960 and 1320),
  closes_minute int not null check (closes_minute between 960 and 1320 and closes_minute > opens_minute),
  has_fridge boolean not null,
  fridge_capacity_kg numeric not null check (fridge_capacity_kg >= 0),
  dry_storage_kg numeric not null check (dry_storage_kg >= 0),
  -- A pantry has a fridge exactly when it has fridge capacity.
  check (has_fridge = (fridge_capacity_kg > 0)),
  anchor boolean not null
);

create table public.drivers (
  id text primary key check (id ~ '^V[0-9]{2}$'),
  name text not null check (char_length(name) between 1 and 200),
  vehicle text not null check (vehicle in ('motorcycle', 'car', 'tricycle', 'bicycle')),
  capacity_load_units int not null check (capacity_load_units > 0),
  street text not null check (char_length(street) between 1 and 200),
  available_from_minute int not null check (available_from_minute between 960 and 1320),
  available_to_minute int not null check (available_to_minute between 960 and 1320
    and available_to_minute > available_from_minute),
  -- Tuning counts from drivers.csv. Frozen reference values, not live state.
  tuning_runs int not null check (tuning_runs >= 0),
  tuning_shows int not null check (tuning_shows between 0 and tuning_runs),
  reliability_estimate_frozen numeric not null check (reliability_estimate_frozen between 0 and 1),
  anchor boolean not null
);

-- RLS on, and nothing for anon. Authenticated users (including anonymous sign-ins) may read.
alter table public.donors enable row level security;
alter table public.pantries enable row level security;
alter table public.drivers enable row level security;

revoke all on public.donors, public.pantries, public.drivers from anon, authenticated;
grant select on public.donors, public.pantries, public.drivers to authenticated;
grant select on public.donors, public.pantries, public.drivers to service_role;

create policy donors_read on public.donors for select to authenticated using (true);
create policy pantries_read on public.pantries for select to authenticated using (true);
create policy drivers_read on public.drivers for select to authenticated using (true);
